#!/usr/bin/env node
/**
 * claude-brief-inject.mjs — SessionStart hook
 *
 * Injects the comprehensive audit-driven CLAUDE-BRIEF.md into every Claude
 * session so Mark never has to re-explain PRISM (process priority, CAM status,
 * JM fleet, AI hierarchy, knowledge bridges, gaps, hidden capabilities, safety
 * architecture). Complementary to the lightweight prism-awareness-v2.mjs which
 * answers "where are we right now"; this one answers "what is PRISM."
 *
 * Source: state/shared/CLAUDE-BRIEF.md regenerated by
 *         scripts/generate-claude-brief.mjs (drift monitor + manual).
 *
 * If brief is missing or >24h stale, regenerate before inject.
 * If regen fails, fail-open with a one-line warning so the session still opens.
 */
import { shouldSkipHook as _hp_shouldSkip } from "../helpers/hook-profile.mjs";
import { existsSync, readFileSync, statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";

const REPO_ROOT = "H:/prism";
const BRIEF = path.join(REPO_ROOT, "state/shared/CLAUDE-BRIEF.md");
const GEN = path.join(REPO_ROOT, "mcp-server/scripts/generate-claude-brief.mjs");
const STALENESS_HOURS = 24;
// HS-05 (2026-05-12): drop the inject ceiling so the harness doesn't
// trigger its persisted-output flood (anything >~10 KB lands on disk +
// shows a 2 KB preview AND the disk-file pointer, ~3 KB total wasted on
// duplication). 4 KB still carries the headline + counts + top sections
// — operator reads the full file on demand at state/shared/CLAUDE-BRIEF.md.
const MAX_INJECT_BYTES = Number(process.env.PRISM_CLAUDE_BRIEF_MAX_BYTES || 4000);

function emit(additionalContext) {
  process.stdout.write(JSON.stringify({
    continue: true,
    hookSpecificOutput: {
      hookEventName: "SessionStart",
      additionalContext,
    },
  }));
}

function ageHours(p) {
  if (!existsSync(p)) return Infinity;
  return (Date.now() - statSync(p).mtimeMs) / (1000 * 60 * 60);
}

(async () => {
  if (await _hp_shouldSkip("claude-brief-inject")) {
    process.exit(0);
  }

  try {
    const briefAge = ageHours(BRIEF);
    if (briefAge > STALENESS_HOURS) {
      const node = process.execPath || "node";
      spawnSync(node, [GEN, "--write"], { timeout: 10_000, stdio: "ignore" });
    }

    if (!existsSync(BRIEF)) {
      emit("⚠ CLAUDE-BRIEF.md missing. Run `node H:/prism/mcp-server/scripts/generate-claude-brief.mjs` to generate.");
      process.exit(0);
    }

    let content = readFileSync(BRIEF, "utf8");
    if (content.length > MAX_INJECT_BYTES) {
      content = content.slice(0, MAX_INJECT_BYTES) + `\n\n[truncated — full brief at ${BRIEF}]`;
    }

    emit(content);
    process.exit(0);
  } catch (err) {
    emit(`⚠ claude-brief-inject failed (${err.message}). Run \`node ${GEN}\` manually.`);
    process.exit(0);
  }
})();
